    54	    icon: React.FC<SvgProps> | ImageSourcePropType;
    55	
    56	    /** The custom icon width */
    57	    iconWidth?: number;
    58	
    59	    /** The custom icon height */
    60	    iconHeight?: number;
    61	
    62	    /** Color for the icon (should be from theme) */
    63	    iconColor?: string;
    64	};
    65	
    66	type BlockingViewAnimationProps = {
    67	    /** Animation for the page */
    68	    animation: DotLottieAnimation;
    69	
    70	    /** Style for the animation */
    71	    animationStyles?: StyleProp<ViewStyle>;
    72	
    73	    /** Style for the animation on web */
    74	    animationWebStyle?: WebStyle;
    75	};
    76	
    77	// This page requires either an icon or an animation, but not both
    78	type BlockingViewProps = BaseBlockingViewProps & MergeExclusive<BlockingViewIconProps, BlockingViewAnimationProps>;
    79	
    80	function BlockingView({
    81	    animation,
    82	    icon,
    83	    iconColor,
    84	    title,
    85	    subtitle = '',
    86	    subtitleStyle,
    87	    linkKey = 'notFound.goBackHome',
    88	    shouldShowLink = false,
    89	    iconWidth = variables.iconSizeSuperLarge,
    90	    iconHeight = variables.iconSizeSuperLarge,
    91	    onLinkPress = () => Navigation.dismissModal(),
    92	    shouldEmbedLinkWithSubtitle = false,
    93	    animationStyles = [],
    94	    animationWebStyle = {},
    95	    CustomSubtitle,
    96	    contentFitImage,
    97	    containerStyle,
    98	}: BlockingViewProps) {
    99	    const styles = useThemeStyles();
   100	    const {translate} = useLocalize();
   101	
   102	    const subtitleText = useMemo(
   103	        () => (
   104	            <>
   105	                {subtitle && (
   106	                    <AutoEmailLink
   107	                        style={[styles.textAlignCenter, subtitleStyle]}
   108	                        text={subtitle}
   109	                    />
   110	                )}
   111	                {shouldShowLink ? (
   112	                    <TextLink
   113	                        onPress={onLinkPress}
   114	                        style={[styles.link, styles.mt2]}
   115	                    >
   116	                        {translate(linkKey)}
   117	                    </TextLink>
   118	                ) : null}
   119	            </>
   120	        ),
   121	        [styles, subtitle, shouldShowLink, linkKey, onLinkPress, translate, subtitleStyle],
   122	    );
   123	
   124	    const subtitleContent = useMemo(() => {
   125	        if (CustomSubtitle) {
   126	            return CustomSubtitle;
   127	        }
   128	        return shouldEmbedLinkWithSubtitle ? (
   129	            <Text style={[styles.textAlignCenter]}>{subtitleText}</Text>
   130	        ) : (
   131	            <View style={[styles.alignItemsCenter, styles.justifyContentCenter]}>{subtitleText}</View>
   132	        );
   133	    }, [styles, subtitleText, shouldEmbedLinkWithSubtitle, CustomSubtitle]);
   134	
   135	    return (
   136	        <View style={[styles.flex1, styles.alignItemsCenter, styles.justifyContentCenter, styles.ph10, containerStyle]}>
   137	            {animation && (
   138	                <Lottie
   139	                    source={animation}
   140	                    loop
   141	                    autoPlay
   142	                    style={animationStyles}
   143	                    webStyle={animationWebStyle}
   144	                />
   145	            )}
   146	            {icon && (
   147	                <Icon
   148	                    src={icon}
   149	                    fill={iconColor}
   150	                    width={iconWidth}
   151	                    height={iconHeight}
   152	                    contentFit={contentFitImage}
   153	                />
   154	            )}
   155	            <View>
   156	                <Text style={[styles.notFoundTextHeader]}>{title}</Text>
   157	
   158	                {subtitleContent}
   159	            </View>
   160	        </View>
   161	    );
   162	}
   163	
   164	BlockingView.displayName = 'BlockingView';
   165	
   166	export default BlockingView;
